🚀 <b>React Compiler — автоматическая оптимизация</b>

<b>Проблема раньше:</b>
<code>// Нужно было вручную оптимизировать
const ExpensiveComponent = React.memo(({ data }) => {
  const computed = useMemo(() => heavyComputation(data), [data]);
  const handleClick = useCallback(() => doSomething(), []);

  return &lt;div onClick={handleClick}&gt;{computed}&lt;/div&gt;
});</code>

<b>✅ С React Compiler:</b>
<code>// Компилятор автоматически оптимизирует!
function ExpensiveComponent({ data }) {
  const computed = heavyComputation(data); // Автоматически мемоизируется
  const handleClick = () => doSomething(); // Автоматически мемоизируется

  return &lt;div onClick={handleClick}&gt;{computed}&lt;/div&gt;
}
// Не нужны: React.memo, useMemo, useCallback!</code>

🎯 <b>Что делает компилятор:</b>
1. Автоматически мемоизирует компоненты (как React.memo)
2. Автоматически мемоизирует вычисления (как useMemo)
3. Автоматически мемоизирует функции (как useCallback)
4. Оптимизирует только когда нужно

💡 <b>Преимущества:</b>
• Меньше кода
• Нет ручной оптимизации
• Умнее, чем ручная мемоизация
• Автоматически адаптируется

⚠️ <b>Важно:</b> Компоненты должны быть чистыми функциями!

💬 <b>Оптимистичный чат с useOptimistic</b>

<code>function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);
  const [optimisticMessages, addOptimisticMessage] = useOptimistic(
    messages,
    (state, newMessage) => [...state, { ...newMessage, sending: true }]
  );

  async function sendMessage(text) {
    const tempMessage = {
      id: `temp-${Date.now()}`,
      text,
      author: 'Вы',
      timestamp: new Date()
    };

    // Мгновенно показываем сообщение
    addOptimisticMessage(tempMessage);

    try {
      // Отправляем на сервер
      const response = await fetch(`/api/rooms/${roomId}/messages`, {
        method: 'POST',
        body: JSON.stringify({ text })
      });
      const savedMessage = await response.json();

      // Заменяем временное сообщение на реальное
      setMessages(prev => [...prev, savedMessage]);
    } catch (error) {
      // При ошибке оптимистичное обновление откатится автоматически
      alert('Не удалось отправить сообщение');
    }
  }

  return (
    &lt;div&gt;
      &lt;MessageList messages={optimisticMessages} /&gt;
      &lt;MessageInput onSend={sendMessage} /&gt;
    &lt;/div&gt;
  );
}

function MessageList({ messages }) {
  return messages.map(msg => (
    &lt;div key={msg.id} style={{ opacity: msg.sending ? 0.5 : 1 }}&gt;
      &lt;strong&gt;{msg.author}:&lt;/strong&gt; {msg.text}
      {msg.sending && &lt;span&gt; ⏳&lt;/span&gt;}
    &lt;/div&gt;
  ));
}</code>

🛡️ <b>Error Boundary — перехват ошибок рендеринга</b>

<b>Создание Error Boundary:</b>
<code>class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    // Обновляем state при ошибке
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    // Логируем ошибку
    console.error('Error caught:', error, errorInfo);
    // Можно отправить на сервер логирования
    logErrorToService(error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        &lt;div&gt;
          &lt;h1&gt;Что-то пошло не так 😢&lt;/h1&gt;
          &lt;details&gt;
            {this.state.error && this.state.error.toString()}
          &lt;/details&gt;
        &lt;/div&gt;
      );
    }

    return this.props.children;
  }
}</code>

<b>Использование:</b>
<code>function App() {
  return (
    &lt;ErrorBoundary&gt;
      &lt;Header /&gt;
      &lt;ErrorBoundary&gt;
        &lt;MainContent /&gt;
      &lt;/ErrorBoundary&gt;
      &lt;Footer /&gt;
    &lt;/ErrorBoundary&gt;
  );
}</code>

⚠️ <b>Не ловит:</b>
• Ошибки в обработчиках событий
• Асинхронный код
• SSR ошибки
• Ошибки в самом Error Boundary

🎨 <b>Error Boundary с красивым запасным UI</b>

<code>class ErrorBoundary extends React.Component {
  state = { hasError: false, error: null, errorInfo: null };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({ error, errorInfo });
  }

  resetError = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render() {
    if (this.state.hasError) {
      return (
        &lt;div style={{ padding: '20px', textAlign: 'center' }}&gt;
          &lt;h1&gt;😵 Упс! Что-то сломалось&lt;/h1&gt;
          &lt;p&gt;Мы уже работаем над исправлением&lt;/p&gt;
          &lt;button onClick={this.resetError}&gt;
            🔄 Попробовать снова
          &lt;/button&gt;

          {process.env.NODE_ENV === 'development' && (
            &lt;details style={{ marginTop: '20px', textAlign: 'left' }}&gt;
              &lt;summary&gt;Детали ошибки&lt;/summary&gt;
              &lt;pre&gt;{this.state.error && this.state.error.toString()}&lt;/pre&gt;
              &lt;pre&gt;{this.state.errorInfo && this.state.errorInfo.componentStack}&lt;/pre&gt;
            &lt;/details&gt;
          )}
        &lt;/div&gt;
      );
    }

    return this.props.children;
  }
}</code>

<b>Использование с разными UI:</b>
<code>&lt;ErrorBoundary fallback={&lt;ErrorPage /&gt;}&gt;
  &lt;App /&gt;
&lt;/ErrorBoundary&gt;</code>

🔄 <b>Error Boundary с восстановлением</b>

<code>class ErrorBoundary extends React.Component {
  state = { hasError: false, errorCount: 0 };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState(prev => ({ errorCount: prev.errorCount + 1 }));
    console.error('Error #' + this.state.errorCount, error);
  }

  // Сброс ошибки при изменении children
  componentDidUpdate(prevProps) {
    if (this.state.hasError && prevProps.children !== this.props.children) {
      this.setState({ hasError: false });
    }
  }

  handleReset = () => {
    this.setState({ hasError: false });
  };

  render() {
    if (this.state.hasError) {
      return (
        &lt;div className="error-container"&gt;
          &lt;h1&gt;Произошла ошибка&lt;/h1&gt;
          &lt;p&gt;Попыток восстановления: {this.state.errorCount}&lt;/p&gt;
          &lt;button onClick={this.handleReset}&gt;
            🔄 Попробовать снова
          &lt;/button&gt;
          &lt;button onClick={() => window.location.reload()}&gt;
            🏠 Перезагрузить страницу
          &lt;/button&gt;
        &lt;/div&gt;
      );
    }

    return this.props.children;
  }
}</code>

<b>С автоматическим восстановлением:</b>
<code>componentDidCatch(error, errorInfo) {
  // Автоматически пробуем восстановить через 3 секунды
  setTimeout(() => {
    if (this.state.errorCount < 3) {
      this.setState({ hasError: false });
    }
  }, 3000);
}</code>

⚡ <b>Оптимизация компонентов с хуками</b>

<b>1. React.memo для пропсов:</b>
<code>const ExpensiveChild = React.memo(({ data, onClick }) => {
  return &lt;div onClick={onClick}&gt;{data}&lt;/div&gt;
});</code>

<b>2. useCallback для функций:</b>
<code>function Parent() {
  const handleClick = useCallback(() => {
    console.log('Click');
  }, []); // Функция создаётся один раз

  return &lt;ExpensiveChild onClick={handleClick} /&gt;
}</code>

<b>3. useMemo для вычислений:</b>
<code>function Component({ items }) {
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => a.name.localeCompare(b.name));
  }, [items]);

  return sortedItems.map(...);
}</code>

<b>4. Разделение состояния:</b>
<code>// ❌ Плохо — всё в одном state
const [state, setState] = useState({ name: '', age: 0, email: '' });

// ✅ Хорошо — раздельные state
const [name, setName] = useState('');
const [age, setAge] = useState(0);
const [email, setEmail] = useState('');</code>

<b>5. Ленивая инициализация:</b>
<code>// ❌ Плохо — вычисляется при каждом рендере
const [state, setState] = useState(expensiveComputation());

// ✅ Хорошо — вычисляется один раз
const [state, setState] = useState(() => expensiveComputation());</code>

💡 <b>Правило:</b> Оптимизируйте только после измерения производительности!

🔍 <b>Поиск лишних рендеров</b>

<b>1. React DevTools Profiler:</b>
<code>// В браузере:
// DevTools → Profiler → Record → Выполните действие → Stop
// Смотрите, какие компоненты рендерятся и почему</code>

<b>2. Кастомный хук для отладки:</b>
<code>function useWhyDidYouUpdate(name, props) {
  const previousProps = useRef();

  useEffect(() => {
    if (previousProps.current) {
      const allKeys = Object.keys({ ...previousProps.current, ...props });
      const changedProps = {};

      allKeys.forEach(key => {
        if (previousProps.current[key] !== props[key]) {
          changedProps[key] = {
            from: previousProps.current[key],
            to: props[key]
          };
        }
      });

      if (Object.keys(changedProps).length > 0) {
        console.log('[why-did-you-update]', name, changedProps);
      }
    }

    previousProps.current = props;
  });
}

// Использование:
function MyComponent(props) {
  useWhyDidYouUpdate('MyComponent', props);
  return &lt;div&gt;...&lt;/div&gt;
}</code>

<b>3. Логирование рендеров:</b>
<code>function Component({ data }) {
  console.log('Component render', { data });

  useEffect(() => {
    console.log('Component mounted');
    return () => console.log('Component unmounted');
  }, []);

  return &lt;div&gt;{data}&lt;/div&gt;
}</code>

🚀 <b>Миграция на React 19</b>

<b>✅ Новые возможности:</b>
1. React Compiler — автоматическая оптимизация
2. Actions — упрощённая работа с формами
3. use() — новый хук для промисов
4. useOptimistic — оптимистичные обновления
5. Automatic Batching везде

<b>⚠️ Breaking Changes:</b>
<code>// 1. ref как обычный проп (не нужен forwardRef)
// Раньше:
const Input = forwardRef((props, ref) => {
  return &lt;input ref={ref} {...props} /&gt;
});

// Теперь:
function Input({ ref, ...props }) {
  return &lt;input ref={ref} {...props} /&gt;
}

// 2. Context.Provider → Context
// Раньше:
&lt;ThemeContext.Provider value={theme}&gt;

// Теперь:
&lt;ThemeContext value={theme}&gt;</code>

<b>📋 Чеклист миграции:</b>
1. Обновите зависимости: react@19, react-dom@19
2. Проверьте использование forwardRef
3. Обновите Context.Provider
4. Протестируйте формы с новыми Actions
5. Включите React Compiler (опционально)
6. Удалите лишние useMemo/useCallback (с компилятором)

💡 <b>Совет:</b> Миграция постепенная, старый код продолжит работать!

React JS, или просто React, это открытая библиотека JavaScript для создания пользовательских интерфейсов, особенно для одностраничных приложений (SPA). Ключевые особенности React:
1) Компонентный подход: React строится на концепции компонентов, что позволяет разработчикам создавать легко переиспользуемые куски кода;
2) Виртуальный DOM: React использует виртуальный DOM для отслеживания изменений. Это абстракция реального DOM, что позволяет библиотеке обновлять только те части интерфейса, которые действительно изменились, вместо полного перерендеринга страницы. Это делает React относительно быстрым;
3) Хуки: Введение хуков позволило использовать состояния и другие возможности классовых компонентов в функциональных компонентах, что сделало код более кратким и чистым;
4) Сообщество и экосистема: React имеет большое и активное сообщество разработчиков, а также много библиотек и инструментов, созданных сообществом, что облегчает разработку сложных приложений.

Подробнее: <a href='https://youtu.be/R_39q-vdOaE?si=mEKDaYDjEdnojG-N' target='_blank'>Введение в React (видео)</a>

nodejs.answer:
🔄 <b>Event Loop — сердце асинхронности Node.js</b>

<b>Что это:</b>
Механизм, который позволяет Node.js обрабатывать множество операций одновременно без многопоточности. Он постоянно проверяет очередь событий и выполняет связанные callback-функции.

<b>Как работает:</b>
<code>console.log('Старт');

setTimeout(() => {
  console.log('Прошла секунда!');
}, 1000);

fs.readFile('file.txt', () => {
  console.log('Файл готов!');
});

console.log('Финиш');

// Вывод:
// Старт
// Финиш
// Файл готов!
// Прошла секунда!</code>

💡 <b>Преимущества:</b>
• Одновременное чтение файлов
• Ответы на запросы
• Работа с таймерами
• Всё без блокировки!

🎯 <b>Это делает Node.js быстрым для асинхронных задач!</b>

⚡ <b>process.nextTick() vs setImmediate()</b>

<b>🕒 process.nextTick()</b>
• Выполняется СРАЗУ после текущей операции
• ДО перехода к следующей фазе Event Loop
• Имеет наивысший приоритет
<code>console.log('1');
process.nextTick(() => console.log('2'));
console.log('3');
// Вывод: 1, 3, 2</code>

<b>⏱️ setImmediate()</b>
• Выполняется в фазе Check
• ПОСЛЕ завершения I/O событий
• Ниже приоритет, чем nextTick
<code>console.log('1');
setImmediate(() => console.log('2'));
console.log('3');
// Вывод: 1, 3, 2 (но позже nextTick)</code>

<b>Сравнение:</b>
<code>process.nextTick(() => console.log('nextTick'));
setImmediate(() => console.log('setImmediate'));
// Вывод:
// nextTick
// setImmediate</code>

💡 <b>Когда использовать:</b>
• nextTick — для очистки, избежания рекурсии
• setImmediate — после I/O операций

💾 <b>I/O — Input/Output (Ввод/Вывод)</b>

<b>Ввод (Input):</b>
• Получение данных из внешнего источника
• Чтение файла
• Получение данных из сети
• Ввод пользователя
<code>fs.readFile('data.txt', (err, data) => {
  console.log(data); // Ввод из файла
});</code>

<b>Вывод (Output):</b>
• Отправка данных во внешнюю систему
• Запись в файл
• Отправка HTTP-ответа
• Вывод в консоль
<code>fs.writeFile('output.txt', 'Hello', () => {
  console.log('Записано!'); // Вывод в файл
});</code>

<b>Блокирующий vs Неблокирующий I/O:</b>
<code>// ❌ Блокирующий (синхронный)
const data = fs.readFileSync('file.txt');
console.log(data); // Программа ждёт

// ✅ Неблокирующий (асинхронный)
fs.readFile('file.txt', (err, data) => {
  console.log(data);
});
console.log('Продолжаю работать...'); // Не ждёт!</code>

🎯 <b>Node.js ценится за неблокирующий I/O!</b>

🧵 <b>Worker Threads — многопоточность в Node.js</b>

<b>Что это:</b>
Модуль для создания отдельных потоков для CPU-интенсивных задач. Каждый воркер имеет свой V8 движок и изолированную память.

<b>Когда использовать:</b>
• Тяжёлые вычисления (Фибоначчи, обработка изображений)
• Сложные математические операции
• Парсинг больших данных

<b>Пример:</b>
<code>const { Worker } = require('worker_threads');

// Основной поток
const worker = new Worker('./worker.js', {
  workerData: { n: 40 }
});

worker.on('message', (result) => {
  console.log('Результат:', result);
});

console.log('Основной поток продолжает работать...');

// worker.js
const { parentPort, workerData } = require('worker_threads');

function fibonacci(n) {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

const result = fibonacci(workerData.n);
parentPort.postMessage(result);</code>

<b>Особенности:</b>
• Воркеры изолированы
• Обмен данными через сообщения
• Потребляют больше памяти
• Не для I/O (используйте libuv)

💡 <b>Worker Threads ≠ Libuv пул потоков!</b>

⚙️ <b>process — глобальный объект для управления процессом</b>

<b>Основные свойства:</b>
<code>// Переменные окружения
console.log(process.env.NODE_ENV); // 'production'

// Аргументы командной строки
console.log(process.argv); // ['node', 'app.js', '--port', '3000']

// Текущая директория
console.log(process.cwd()); // '/home/user/project'

// Версия Node.js
console.log(process.version); // 'v18.16.0'

// Платформа
console.log(process.platform); // 'linux', 'win32', 'darwin'</code>

<b>Управление процессом:</b>
<code>// Завершить процесс
process.exit(0); // 0 = успех, 1 = ошибка

// Обработка ошибок
process.on('uncaughtException', (err) => {
  console.error('Необработанная ошибка:', err);
  process.exit(1);
});

// Обработка промисов
process.on('unhandledRejection', (reason) => {
  console.error('Необработанный промис:', reason);
});</code>

<b>Полезные методы:</b>
<code>// Использование памяти
console.log(process.memoryUsage());

// Время работы процесса
console.log(process.uptime()); // в секундах</code>

💡 <b>process доступен глобально, не требует require!</b>

📁 <b>__dirname и __filename — пути к текущему файлу</b>

<b>__dirname:</b>
Абсолютный путь к директории текущего файла
<code>// В файле /home/user/project/src/app.js
console.log(__dirname);
// Вывод: /home/user/project/src</code>

<b>__filename:</b>
Абсолютный путь к текущему файлу
<code>// В файле /home/user/project/src/app.js
console.log(__filename);
// Вывод: /home/user/project/src/app.js</code>

<b>Практическое применение:</b>
<code>const path = require('path');

// Путь к файлу относительно текущего
const configPath = path.join(__dirname, 'config', 'database.json');
// /home/user/project/src/config/database.json

// Чтение файла
const fs = require('fs');
fs.readFile(path.join(__dirname, 'data.txt'), 'utf8', (err, data) => {
  console.log(data);
});</code>

<b>В ES Modules (import/export):</b>
<code>import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);</code>

💡 <b>Используйте для кроссплатформенных путей!</b>

🔗 <b>Middleware — промежуточное ПО</b>

<b>Что это:</b>
Функции, которые имеют доступ к объектам запроса (req), ответа (res) и следующей функции (next) в цикле "запрос-ответ".

<b>Что может делать middleware:</b>
• Выполнять любой код
• Изменять req и res
• Завершать цикл запрос-ответ
• Вызывать следующий middleware

<b>Пример:</b>
<code>// Логирование запросов
app.use((req, res, next) => {
  console.log(`${req.method} ${req.url}`);
  next(); // Передаём управление дальше
});

// Проверка авторизации
function authMiddleware(req, res, next) {
  if (!req.headers.authorization) {
    return res.status(401).json({ error: 'Не авторизован' });
  }
  next();
}

app.get('/profile', authMiddleware, (req, res) => {
  res.json({ user: 'John' });
});</code>

<b>Типы middleware:</b>
• Application-level (app.use)
• Router-level (router.use)
• Error-handling
• Built-in (express.json)
• Third-party (cors, helmet)

💡 <b>Middleware выполняются по порядку!</b>

🌊 <b>Streams — потоки данных</b>

<b>Что это:</b>
Механизм для работы с данными по частям (chunks), вместо загрузки всего в память. Идеально для больших файлов!

<b>4 типа потоков:</b>

<b>1️⃣ Readable (Читаемые)</b>
• Чтение данных из источника
<code>const readStream = fs.createReadStream('big-file.txt');
readStream.on('data', (chunk) => {
  console.log('Получен кусок:', chunk.length);
});</code>

<b>2️⃣ Writable (Записываемые)</b>
• Запись данных в пункт назначения
<code>const writeStream = fs.createWriteStream('output.txt');
writeStream.write('Hello ');
writeStream.write('World!');
writeStream.end();</code>

<b>3️⃣ Duplex (Дуплексные)</b>
• Одновременно читаемые и записываемые
• Пример: TCP-сокеты

<b>4️⃣ Transform (Трансформирующие)</b>
• Изменяют данные "на лету"
<code>const { Transform } = require('stream');
const upperCase = new Transform({
  transform(chunk, encoding, callback) {
    this.push(chunk.toString().toUpperCase());
    callback();
  }
});</code>

💡 <b>Streams экономят память!</b>

🔗 <b>pipe() — соединение потоков</b>

<b>Что делает:</b>
Метод .pipe() соединяет Readable-поток с Writable-потоком для автоматической передачи данных. Чтение новой порции не начинается, пока предыдущая не записана.

<b>Пример — копирование файла:</b>
<code>const fs = require('fs');

const readStream = fs.createReadStream('input.txt');
const writeStream = fs.createWriteStream('output.txt');

readStream.pipe(writeStream);

writeStream.on('finish', () => {
  console.log('Файл скопирован!');
});</code>

<b>Цепочка pipe с Transform:</b>
<code>const { Transform } = require('stream');
const zlib = require('zlib');

// Чтение → Сжатие → Запись
fs.createReadStream('input.txt')
  .pipe(zlib.createGzip()) // Сжимаем
  .pipe(fs.createWriteStream('input.txt.gz'))
  .on('finish', () => console.log('Сжато!'));</code>

💡 <b>pipe() синхронизирует скорость чтения и записи!</b>

📈 <b>3 способа масштабирования</b>

<b>1️⃣ Модуль cluster</b>
• Запускает несколько копий приложения на одном сервере
• Использует все ядра процессора
<code>const cluster = require('cluster');
const os = require('os');

if (cluster.isMaster) {
  const numCPUs = os.cpus().length;
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork(); // Создаём воркеры
  }
} else {
  // Код приложения
  require('./app');
}</code>

<b>2️⃣ Балансировка нагрузки (Nginx)</b>
• Распределяет запросы между серверами
• Можно добавлять новые серверы

<b>3️⃣ Docker контейнеры</b>
• Упаковка приложения в контейнер
• Легко масштабировать и переносить
<code>docker run -d --name app1 myapp
docker run -d --name app2 myapp</code>

💡 <b>Выбор зависит от нагрузки!</b>

👥 <b>Cluster — использование всех ядер CPU</b>

<b>Проблема:</b>
Node.js однопоточный, использует только 1 ядро процессора.

<b>Решение — cluster:</b>
• Создаёт несколько процессов (воркеров)
• Один мастер-процесс управляет воркерами
• Все воркеры делят один порт
• Запросы распределяются автоматически

<b>Пример:</b>
<code>const cluster = require('cluster');
const http = require('http');
const numCPUs = require('os').cpus().length;

if (cluster.isMaster) {
  console.log(`Мастер ${process.pid} запущен`);

  // Создаём воркеры
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  // Перезапуск при падении
  cluster.on('exit', (worker) => {
    console.log(`Воркер ${worker.process.pid} умер`);
    cluster.fork();
  });
} else {
  // Воркеры создают HTTP-сервер
  http.createServer((req, res) => {
    res.end('Hello from ' + process.pid);
  }).listen(3000);
}</code>

💡 <b>Воркеры не делят состояние — используйте Redis!</b>

💾 <b>Buffer — работа с бинарными данными</b>

<b>Что это:</b>
Встроенный класс для работы с бинарными данными. Представляет область памяти фиксированного размера вне кучи V8.

<b>Создание Buffer:</b>
<code>// Из строки
const buf1 = Buffer.from('Hello');
console.log(buf1); // &lt;Buffer 48 65 6c 6c 6f&gt;

// Пустой буфер размером 10 байт
const buf2 = Buffer.alloc(10);

// Из массива байтов
const buf3 = Buffer.from([72, 101, 108, 108, 111]);
console.log(buf3.toString()); // 'Hello'</code>

<b>Работа с Buffer:</b>
<code>const buf = Buffer.from('Hello World');

// Чтение
console.log(buf[0]); // 72 (код 'H')
console.log(buf.toString()); // 'Hello World'
console.log(buf.toString('hex')); // '48656c6c6f20576f726c64'

// Запись
buf.write('Hi', 0);
console.log(buf.toString()); // 'Hillo World'</code>

💡 <b>Используется для файлов, сокетов, криптографии!</b>

🛣️ <b>path — работа с путями файлов</b>

<b>Зачем нужен:</b>
Делает код кроссплатформенным (Windows использует \, Linux/Mac — /)

<b>Основные методы:</b>
<code>const path = require('path');

// Соединить пути
const fullPath = path.join('/home', 'user', 'docs', 'file.txt');
// '/home/user/docs/file.txt'

// Абсолютный путь
const absPath = path.resolve('docs', 'file.txt');
// '/current/directory/docs/file.txt'

// Имя файла
const filename = path.basename('/home/user/file.txt');
// 'file.txt'

// Директория
const dir = path.dirname('/home/user/file.txt');
// '/home/user'

// Расширение
const ext = path.extname('file.txt');
// '.txt'

// Разобрать путь
const parsed = path.parse('/home/user/file.txt');
// { root: '/', dir: '/home/user', base: 'file.txt', ext: '.txt', name: 'file' }</code>

💡 <b>Всегда используйте path для кроссплатформенности!</b>

