📡 <b>events — событийная модель</b>

<b>EventEmitter:</b>
Класс для работы с событиями. Практически все модули Node.js используют событийную модель.

<b>Основные методы:</b>
<code>const EventEmitter = require('events');
const emitter = new EventEmitter();

// Подписка на событие
emitter.on('data', (message) => {
  console.log('Получено:', message);
});

// Одноразовая подписка
emitter.once('connect', () => {
  console.log('Подключено!');
});

// Генерация события
emitter.emit('data', 'Hello World');
emitter.emit('connect');</code>

<b>Создание своего EventEmitter:</b>
<code>class MyEmitter extends EventEmitter {}

const myEmitter = new MyEmitter();

myEmitter.on('event', () => {
  console.log('Событие произошло!');
});

myEmitter.emit('event');</code>

<b>Удаление слушателей:</b>
<code>const callback = () => console.log('Hello');
emitter.on('test', callback);
emitter.off('test', callback); // Удалить
emitter.removeAllListeners('test'); // Удалить все</code>

💡 <b>Streams, HTTP, процессы — все используют события!</b>

🌐 <b>HTTP-сервер на чистом Node.js</b>

<b>Простой сервер:</b>
<code>const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('Hello World!');
});

server.listen(3000, () => {
  console.log('Сервер запущен на http://localhost:3000');
});</code>

<b>Роутинг:</b>
<code>const server = http.createServer((req, res) => {
  if (req.url === '/' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('&lt;h1&gt;Главная&lt;/h1&gt;');
  } else if (req.url === '/api/users' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ users: ['John', 'Jane'] }));
  } else {
    res.writeHead(404);
    res.end('Not Found');
  }
});</code>

<b>Обработка POST:</b>
<code>if (req.method === 'POST') {
  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    const data = JSON.parse(body);
    res.end('Получено: ' + data.name);
  });
}</code>

💡 <b>Для production используйте Express!</b>

⚡ <b>Express — минималистичный веб-фреймворк</b>

<b>Зачем нужен:</b>
• Упрощает создание HTTP-серверов
• Удобная маршрутизация
• Middleware для обработки запросов
• Поддержка шаблонов
• Обработка статических файлов

<b>Установка и базовый сервер:</b>
<code>npm install express

const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.get('/api/users', (req, res) => {
  res.json({ users: ['John', 'Jane'] });
});

app.post('/api/users', (req, res) => {
  res.status(201).json({ message: 'Создано' });
});

app.listen(3000, () => {
  console.log('Сервер на http://localhost:3000');
});</code>

<b>Middleware:</b>
<code>// Парсинг JSON
app.use(express.json());

// Логирование
app.use((req, res, next) => {
  console.log(`${req.method} ${req.url}`);
  next();
});</code>

💡 <b>Express — стандарт для Node.js API!</b>
